 void unlockCode(JSONObject device,boolean temporary){if(busy)return;busy=true;worker.execute(()->{try{JSONObject result=call("POST","/api/admin/devices/"+device.getString("id")+(temporary?"/temporary-unlock-code":"/unlock-code"),new JSONObject(),true);String code=result.optString("code");if(!code.matches("[0-9]{10}")||(temporary&&result.optInt("duration_seconds")!=300))throw new IOException("The server did not return a valid unlock code.");ui(()->{busy=false;String shown=code.substring(0,5)+" "+code.substring(5);String purpose=temporary?"five-minute access code":"unlock code";String entry=temporary?"Five-minute access code":"Enter unlock code";String details=temporary?"Five minutes starts when this code is verified. Internet is needed once; the timer then runs on the phone, even offline. Normal finance restrictions resume when it ends. No payment is added. Requires customer app 0.22.0 or later.":"Only restores recorded paid access. Internet is required. No payment is added.";String message="Loop Secure "+purpose+": "+shown+". One use, for your phone only. Code expires "+dateTime(result.optLong("expires"))+". Enter it in Loop Secure → Support → "+entry+". "+details;new MaterialAlertDialogBuilder(this).setTitle(temporary?"Five-minute access code":"One-use unlock code").setMessage(shown+"\n\nCode expires "+dateTime(result.optLong("expires"))+"\n\n"+details).setPositiveButton("Copy",(dialog,which)->{android.content.ClipData clip=android.content.ClipData.newPlainText("Loop Secure "+purpose,message);android.os.PersistableBundle extra=new android.os.PersistableBundle();extra.putBoolean("android.content.extra.IS_SENSITIVE",true);clip.getDescription().setExtras(extra);getSystemService(android.content.ClipboardManager.class).setPrimaryClip(clip);}).setNeutralButton("WhatsApp",(dialog,which)->{String phone=device.optString("phone").replaceAll("[^0-9]","");if(phone.startsWith("0")&&phone.length()==10)phone="27"+phone.substring(1);if(!phone.matches("[1-9][0-9]{7,14}")){notice="Customer phone number is invalid. Generate and copy a fresh code instead.";render();return;}startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://wa.me/"+phone+"?text="+Uri.encode(message))));}).setNegativeButton("Close",null).show();});}catch(Exception e){fail(e);}});}
 void command(JSONObject d,String action){if(busy)return;busy=true;worker.execute(()->{try{call("POST","/api/admin/devices/"+d.getString("id")+"/control",new JSONObject().put("action",action).put("request_key",UUID.randomUUID().toString()),true);ui(()->{busy=false;notice="Command queued. The phone has not confirmed it yet.";refresh();});}catch(Exception e){fail(e);}});}
