 String rawQr(JSONObject data)throws Exception{HttpsURLConnection c=(HttpsURLConnection)new URL(BASE+"/api/admin/provisioning/qr").openConnection();c.setRequestMethod("POST");c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setDoOutput(true);c.setRequestProperty("Authorization","Bearer "+store.get("access_token"));c.setRequestProperty("Content-Type","application/json");try{try(OutputStream out=c.getOutputStream()){out.write(data.toString().getBytes(StandardCharsets.UTF_8));}if(c.getResponseCode()!=200)throw new IOException("Could not generate enrollment QR");try(InputStream input=c.getInputStream()){byte[] bytes=za.co.bacy.ui.BoundedInput.read(input,300000);return new String(bytes,StandardCharsets.UTF_8);}}finally{c.disconnect();}}
